-- 47 Autumn Run: runs the fox and switches how the camera follows it. The
-- following itself is the engine's - `camera_follow` with a dead zone and
-- look-ahead, changed by Camera.set_follow - and the parallax and the dead
-- zone box are placed from Camera.get_position. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/47-autumn-run.scene"
local GROUND = { { -1000.0, -165.1 }, { -940.0, -183.3 }, { -880.0, -206.1 }, { -820.0, -228.5 }, { -760.0, -245.8 }, { -700.0, -255.5 }, { -640.0, -257.3 }, { -580.0, -253.1 }, { -520.0, -246.2 }, { -460.0, -239.2 }, { -400.0, -233.5 }, { -340.0, -228.8 }, { -280.0, -222.8 }, { -220.0, -213.0 }, { -160.0, -197.5 }, { -100.0, -176.4 }, { -40.0, -152.2 }, { 20.0, -128.9 }, { 80.0, -111.4 }, { 140.0, -103.2 }, { 200.0, -105.6 }, { 260.0, -117.1 }, { 320.0, -133.6 }, { 380.0, -149.6 }, { 440.0, -160.3 }, { 500.0, -162.4 }, { 560.0, -155.7 }, { 620.0, -142.6 }, { 680.0, -127.2 }, { 740.0, -113.8 }, { 800.0, -105.5 }, { 860.0, -103.3 }, { 920.0, -106.0 }, { 980.0, -111.1 }, { 1040.0, -115.9 }, { 1100.0, -119.0 }, { 1160.0, -120.8 }, { 1220.0, -123.4 }, { 1280.0, -129.9 }, { 1340.0, -143.0 }, { 1400.0, -163.5 }, { 1460.0, -189.7 }, { 1520.0, -217.8 }, { 1580.0, -242.6 }, { 1640.0, -259.1 }, { 1700.0, -264.4 }, { 1760.0, -258.2 }, { 1820.0, -243.4 }, { 1880.0, -224.6 }, { 1940.0, -207.3 }, { 2000.0, -195.5 }, { 2060.0, -191.2 }, { 2120.0, -193.5 }, { 2180.0, -199.6 }, { 2240.0, -205.8 }, { 2300.0, -209.1 }, { 2360.0, -208.2 }, { 2420.0, -203.8 }, { 2480.0, -198.3 }, { 2540.0, -194.2 }, { 2600.0, -193.3 }, { 2660.0, -195.4 }, { 2720.0, -198.3 }, { 2780.0, -198.5 }, { 2840.0, -192.4 }, { 2900.0, -177.8 }, { 2960.0, -155.0 }, { 3020.0, -127.1 }, { 3080.0, -99.0 }, { 3140.0, -76.3 }, { 3200.0, -63.6 }, { 3260.0, -62.6 }, { 3320.0, -72.6 }, { 3380.0, -89.8 }, { 3440.0, -109.4 }, { 3500.0, -126.8 }, { 3560.0, -139.1 }, { 3620.0, -145.8 }, { 3680.0, -148.6 }, { 3740.0, -150.3 }, { 3800.0, -153.7 }, { 3860.0, -160.0 }, { 3920.0, -168.8 }, { 3980.0, -177.6 }, { 4040.0, -183.6 }, { 4100.0, -184.6 }, { 4160.0, -180.0 }, { 4220.0, -171.8 }, { 4280.0, -163.6 }, { 4340.0, -160.1 }, { 4400.0, -164.6 }, { 4460.0, -178.7 }, { 4520.0, -200.9 }, { 4580.0, -227.0 }, { 4640.0, -251.5 }, { 4700.0, -269.2 }, { 4760.0, -276.5 }, { 4820.0, -272.8 }, { 4880.0, -260.1 }, { 4940.0, -242.3 }, { 5000.0, -223.8 }, { 5060.0, -208.0 }, { 5120.0, -196.2 }, { 5180.0, -187.6 }, { 5240.0, -179.9 }, { 5300.0, -170.7 }, { 5360.0, -158.8 }, { 5420.0, -144.6 }, { 5480.0, -130.5 }, { 5540.0, -119.9 }, { 5600.0, -116.0 }, { 5660.0, -120.1 }, { 5720.0, -131.1 }, { 5780.0, -145.7 }, { 5840.0, -159.0 }, { 5900.0, -166.2 }, { 5960.0, -164.1 }, { 6020.0, -152.3 }, { 6080.0, -133.5 }, { 6140.0, -112.2 }, { 6200.0, -93.9 }, { 6260.0, -83.0 }, { 6320.0, -81.5 }, { 6380.0, -88.9 }, { 6440.0, -102.4 }, { 6500.0, -118.3 }, { 6560.0, -133.2 }, { 6620.0, -145.5 }, { 6680.0, -155.6 }, { 6740.0, -165.2 }, { 6800.0, -176.8 }, { 6860.0, -192.0 }, { 6920.0, -210.4 }, { 6980.0, -229.7 }, { 7040.0, -246.1 }, { 7100.0, -255.5 }, { 7160.0, -255.3 }, { 7220.0, -245.1 }, { 7280.0, -227.6 }, { 7340.0, -207.3 }, { 7400.0, -189.6 } }
local LAYERS = { { name = "Mountains", f = 0.12, y = -10.0 }, { name = "HillsFar", f = 0.35, y = -120.0 } }
local RANGE = 6700.0
local MODES = {
    { name = "plain follow", zone = { 0, 0 }, ahead = 0 },
    { name = "dead zone", zone = { 360, 240 }, ahead = 0 },
    { name = "look-ahead", zone = { 0, 0 }, ahead = 0.55 },
    { name = "dead zone + look-ahead", zone = { 360, 240 }, ahead = 0.55 },
}
local captions, show_box = true, true
local fox, leaves, aim, status, sky, sun
local bars = {}
local mode = 4
local x, y, vx, vy = 0, 0, 0, 0
local grounded, facing, t = true, 1, 0

local function ground_y(px)
    for i = 2, #GROUND do
        if px <= GROUND[i][1] then
            local a, b = GROUND[i - 1], GROUND[i]
            return a[2] + (b[2] - a[2]) * (px - a[1]) / (b[1] - a[1])
        end
    end
    return GROUND[#GROUND][2]
end

local function apply(m)
    mode = m
    Camera.set_follow(fox, "dead_zone", MODES[m].zone)
    Camera.set_follow(fox, "look_ahead", MODES[m].ahead)
end

function init(entity)
    fox = Entity.find_by_name("Fox")
    leaves = Entity.find_by_name("Leaves")
    aim = Entity.find_by_name("Aim")
    status = Entity.find_by_name("Status")
    sky = Entity.find_by_name("Sky")
    sun = Entity.find_by_name("Sun")
    for _, l in ipairs(LAYERS) do l.e = Entity.find_by_name(l.name) end
    for _, side in ipairs({ "Top", "Bottom", "Left", "Right" }) do bars[side] = Entity.find_by_name("Zone" .. side) end
    y = ground_y(x)
    apply(4)
end

local function held(a, b) return Input.is_key_pressed(a) or Input.is_key_pressed(b) end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    for i = 1, 4 do
        if Input.is_key_just_pressed(tostring(i)) then apply(i) end
    end
    if Input.is_key_just_pressed("B") then show_box = not show_box end
    t = t + dt

    -- Run and jump over the ground the spline shape draws.
    local want = 0
    if held("A", "Left") then want = want - 1 end
    if held("D", "Right") then want = want + 1 end
    if want ~= 0 then facing = want end
    vx = vx + (want * 420 - vx) * math.min(1, dt * (want ~= 0 and 3.5 or 5))
    if grounded and (Input.is_key_just_pressed("Space") or Input.is_key_just_pressed("W") or Input.is_key_just_pressed("Up")) then
        vy = 640
        grounded = false
    end
    x = math.max(-700, math.min(RANGE + 300, x + vx * dt))
    local g = ground_y(x)
    if not grounded then
        vy = vy - 1600 * dt
        y = y + vy * dt
        if y <= g then y = g; vy = 0; grounded = true end
    else
        y = g
    end
    local slope = (ground_y(x + 8) - ground_y(x - 8)) / 16
    local bob = (grounded and math.abs(vx) > 30) and math.abs(math.sin(t * 14)) * 4 or 0
    if fox then
        Transform.set_position(fox, x, y + bob)
        Transform.set_scale(fox, facing, 1)
        Transform.set_rotation(fox, grounded and math.atan(slope) * 0.8 or math.max(-0.35, math.min(0.35, vy * 0.0006 * facing)))
    end

    -- Parallax from where the camera is.
    local cx, cy = Camera.get_position()
    for _, l in ipairs(LAYERS) do
        if l.e then Transform.set_position(l.e, cx * (1 - l.f), l.y + cy * (1 - l.f) * 0.6) end
    end
    if sky then Transform.set_position(sky, cx, cy) end
    if sun then Transform.set_position(sun, cx + 320, cy + 150) end
    if leaves then Transform.set_position(leaves, cx + 200, cy + 420) end

    -- The dead zone, drawn round the camera's centre.
    local z = MODES[mode].zone
    local w, h = show_box and z[1] or 0, show_box and z[2] or 0
    Transform.set_position(bars.Top, cx, cy + h / 2)
    Transform.set_position(bars.Bottom, cx, cy - h / 2)
    Transform.set_position(bars.Left, cx - w / 2, cy)
    Transform.set_position(bars.Right, cx + w / 2, cy)
    Transform.set_scale(bars.Top, w, 3)
    Transform.set_scale(bars.Bottom, w, 3)
    Transform.set_scale(bars.Left, 3, h)
    Transform.set_scale(bars.Right, 3, h)
    if aim then
        Transform.set_position(aim, cx, cy)
        Transform.set_scale(aim, show_box and 1 or 0, show_box and 1 or 0)
    end
    if status then UI.set_text(status, "camera: " .. MODES[mode].name) end
end
